/**
 * The 36 moon signs (Player's Book p175), an optional rule at character
 * creation: 12 moons, each with a waxing, a full, and a waning phase.
 *
 * **GENERATED by extract-lore.mjs — do not edit by hand.** Every row was read
 * out of the PDF and held against a second rendering of the same page; the
 * effects are the book's own words, because a paraphrase of a rule is a
 * different rule.
 *
 * **Only characters born in the mortal world have one** — mortals and demi-fey,
 * which in this book means everybody except elves and grimalkins. The sheet
 * says so beside the picker rather than refusing the choice: a table may rule
 * otherwise, and the module has no business being the one to stop them.
 *
 * The d100 range is kept even though nothing rolls on it yet. It is what makes
 * the table the book's table rather than a list of 36 things, and rolling one
 * is the procedure the book actually prescribes.
 */
export interface MoonSign {
  /** The d100 range this sign is rolled on, as the book prints it. */
  range: string;
  /** The moon of the month: Grinning, Dead, Beast, … */
  moon: string;
  phase: "waxing" | "full" | "waning";
  /** What it does, in the book's words. */
  effect: string;
}

