/** "Grinning moon, waxing" — how a sign is named on the sheet and in a block. */
export function moonSignLabel(sign: MoonSign): string {
  return `${sign.moon} moon, ${sign.phase}`;
}

/** The whole thing on one line, which is what the sheet's own field holds. */
export function moonSignLine(sign: MoonSign): string {
  return `${moonSignLabel(sign)} — ${sign.effect}`;
}

/** The moons in the order of the year, each with its three phases. */
export function moonSignsByMoon(): { moon: string; signs: MoonSign[] }[] {
  const order: string[] = [];
  const byMoon = new Map<string, MoonSign[]>();
  for (const sign of MOON_SIGNS) {
    if (!byMoon.has(sign.moon)) {
      byMoon.set(sign.moon, []);
      order.push(sign.moon);
    }
    byMoon.get(sign.moon)!.push(sign);
  }
  return order.map((moon) => ({ moon, signs: byMoon.get(moon)! }));
}
